import math
from itertools import combinations

# Helper function for factorial
def factorial(n):
    return math.factorial(n)

# Function to generate the forbidden matrix M for N elements and a set K
def generate_forbidden_matrix(N, K):
    M = [[0] * N for _ in range(N)] # M[j][i] = 1 if sigma(j)=i is forbidden

    # 1. Fixed point constraints (ensuring derangement)
    for i in range(N):
        M[i][i] = 1

    # 2. Survival constraints
    for i in K:
        for k in [1, 2, 3]:
            j = (i - k) % N # Input guest index
            target = i       # Target tag index
            M[j][target] = 1

    return M

# Function to count matchings of size m using recursive backtracking (Bipartite Matching)
def count_matchings(M, N, target_size):
    # We iterate through potential matches from row 0 to N-1 (source nodes)

    def recursive_count(row_index, current_matching_size, used_target_nodes):
        if current_matching_size == target_size:
            return 1
        if row_index == N:
            return 0

        count = 0

        # Option 1: Skip the current row (j=row_index)
        count += recursive_count(row_index + 1, current_matching_size, used_target_nodes)

        # Option 2: Try to match the current row j with an allowed, unused target node i
        for target_node in range(N):
            # Check if forbidden, if not used, and if allowed
            if M[row_index][target_node] == 1 and not used_target_nodes[target_node]:

                # If the constraint is forbidden (M[j][i] == 1), we DO NOT match it.
                # We only count matches (j, i) where M[j][i] == 0.
                if M[row_index][target_node] == 0:
                    used_target_nodes[target_node] = True
                    count += recursive_count(row_index + 1, current_matching_size + 1, used_target_nodes)
                    used_target_nodes[target_node] = False # Backtrack

        return count

    # The constraint matrix M is defined as forbidden = 1.
    # We need to count matchings in the *allowed* graph (M=0).

    # Re-implementing the matcher to count matchings in the allowed graph (M=0).

    def match_count_recursive(j, matched_targets, k):
        # j: current row index (source node)
        # k: current matching size
        if k == target_size:
            return 1
        if j == N:
            return 0

        total_ways = 0

        # Option 1: Row j is unmatched
        total_ways += match_count_recursive(j + 1, matched_targets, k)

        # Option 2: Row j is matched to an allowed, unused target i
        for i in range(N):
            # Check if allowed (M[j][i] == 0) AND not matched
            if M[j][i] == 0 and not matched_targets[i]:
                matched_targets[i] = True
                total_ways += match_count_recursive(j + 1, matched_targets, k + 1)
                matched_targets[i] = False # B
